package com.metaverse.coin.strategy.job.funding.config;
import com.metaverse.coin.strategy.core.arbitrage.multi.*; import org.springframework.context.annotation.*;
import java.math.BigDecimal; import java.time.Duration;
import java.util.*; import com.metaverse.coin.strategy.core.arbitrage.config.MultiExchangeFundingRateProperties;
@Configuration
public class CrossExchangePaperConfiguration {
 @Bean public PaperPerpetualGateway paperPerpetualGateway(){return new PaperPerpetualGateway();}
 @Bean public PaperExecutionQuoteProvider paperExecutionQuoteProvider(List<CrossExchangeMarketDataProvider> providers,MultiExchangeFundingRateProperties properties){return new L2PaperExecutionQuoteProvider(providers.stream().filter(provider->properties.getExchanges().contains(provider.exchange())).toList(),properties.getCosts(),properties.getMaximumQuoteAge(),properties.getCaptureOrderBookDepth());}
 @Bean public PaperAtomicHedgeExecutor paperAtomicHedgeExecutor(PaperPerpetualGateway g,PaperExecutionQuoteProvider quoteProvider){return new PaperAtomicHedgeExecutor(g,quoteProvider);}
 @Bean public CrossExchangeRiskService crossExchangeRiskService(MultiExchangeFundingRateProperties properties){return new CrossExchangeRiskService(new CrossExchangeRiskService.Limits(properties.getMaxSymbolNotional(),properties.getMaxExchangeNotional(),properties.getMaximumNakedDuration(),properties.getMaximumHoldingDuration(),properties.getExitNetYield(),properties.getMaxMarkPriceDeviation(),properties.getMinimumHoldingDuration()));}
 @Bean public CrossExchangePaperTradingService crossExchangePaperTradingService(PaperAtomicHedgeExecutor e,CrossExchangeRiskService r,CrossExchangeArbitragePersistenceService p){return new CrossExchangePaperTradingService(e,r,p);}
 @Bean public ExchangeHealthRegistry exchangeHealthRegistry(){return new ExchangeHealthRegistry();}
 @Bean public PerpetualContractCatalog perpetualContractCatalog(List<PerpetualExchangeGateway> gateways,ExchangeHealthRegistry health,MultiExchangeFundingRateProperties properties){return new PerpetualContractCatalog(gateways.stream().filter(gateway->properties.getExchanges().contains(gateway.exchange())).toList(),health);}
 @Bean public FundingPairRiskSizer fundingPairRiskSizer(MultiExchangeFundingRateProperties p){return new FundingPairRiskSizer(new FundingPairRiskSizer.Limits(p.getPaperCapitalPerExchange(),p.getMaximumPaperLeverage(),p.getMaintenanceMarginRate(),p.getMinimumLiquidationDistance(),p.getUnknownSymbolLiquidationDistance(),p.getMaximumLiquidationDistance(),p.getVolatilityMultiplier(),p.getJumpMultiplier(),p.getMinimumRiskHistory(),Duration.ofHours(24),p.getMinimumOrderBookCoverageRatio(),p.getMaximumLegVwapImpact()));}
 @Bean public CrossExchangeOpportunityScanService crossExchangeOpportunityScanService(List<CrossExchangeMarketDataProvider> providers,MultiExchangeFundingRateProperties properties,ExchangeHealthRegistry health,PerpetualContractCatalog catalog,FundingPairRiskSizer riskSizer){DirectionalBasisAdmissionGate basisGate=new DirectionalBasisAdmissionGate(properties.isDirectionalBasisGateEnabled(),properties.getDirectionalBasisMinimumSamples(),properties.getDirectionalBasisWindowSize(),properties.getDirectionalBasisPercentile());return new CrossExchangeOpportunityScanService(providers.stream().filter(provider->properties.getExchanges().contains(provider.exchange())).toList(),new CrossExchangeOpportunitySelector(basisGate),new CrossExchangeOpportunityStabilityGate(properties.getStabilityWindow()),new CrossExchangeOpportunitySelector.Limits(properties.getMaximumQuoteAge(),properties.getMaximumSettlementSkew(),properties.getMaxMarkPriceDeviation(),properties.getMinimumNotional(),properties.getMinNetYieldRate(),properties.getBasisRiskBuffer(),properties.isAllowMixedFundingSigns(),properties.getMinimumCostCoverageRatio(),properties.getMaxExecutableBasis(),properties.getMinimumOrderBookNotional(),properties.getMinimumOrderBookCoverageRatio(),properties.getMaximumLegVwapImpact(),properties.getExpectedHoldingWindows(),properties.getMinimumHorizonNetYield()),properties.getCosts(),properties.getTargetNotional(),health,catalog,properties.getCaptureOrderBookDepth(),riskSizer);}
 @Bean public CrossExchangePositionMonitorService crossExchangePositionMonitorService(List<CrossExchangeMarketDataProvider> providers,CrossExchangeRiskService risk,CrossExchangePaperTradingService paper,CrossExchangeArbitragePersistenceService persistence,MultiExchangeFundingRateProperties properties){return new CrossExchangePositionMonitorService(providers,risk,paper,persistence,properties.getCosts(),properties.getBasisRiskBuffer(),properties.getMaximumQuoteAge(),properties.getMaximumSettlementSkew(),properties.getCaptureOrderBookDepth());}
}
